def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    desperate_count = 0
    rich_count = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 1:
                desperate_count += 1
            if opp.get('budget', 0) >= 180:
                rich_count += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                try:
                    prev_bids.append(float(prev['bid']))
                except Exception:
                    pass

    if not alive:
        return max(0.0, min(float(budget), 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    danger = 0
    if hp <= 2:
        danger += 2
    elif hp <= 4:
        danger += 1
    if no_water_days >= 1:
        danger += 2

    base = 24.0 + 18.0 * scarcity

    if hp >= 7 and no_water_days == 0 and supply >= 21:
        base = 16.0
    elif hp >= 5 and no_water_days == 0 and supply >= 19:
        base = 22.0

    if highest_prev >= 160:
        base -= 6.0
    elif highest_prev <= 90 and highest_prev > 0:
        base += 8.0

    if desperate_count >= 2 and supply <= 18:
        base += 18.0
    elif desperate_count >= 1 and supply <= 17:
        base += 10.0

    if rich_count >= 2 and supply <= 17:
        base += 8.0

    if danger >= 3:
        bid = max(base, min(budget, highest_prev + 3.0 if highest_prev > 0 else 78.0))
    elif danger == 1 or danger == 2:
        bid = max(base, min(budget, avg_prev + 2.0 if avg_prev > 0 else 52.0))
    else:
        bid = base

    if day >= 8 and hp >= 5 and no_water_days == 0:
        bid -= 4.0

    if budget < 120:
        bid = min(bid, 0.55 * budget)
    elif budget < 200:
        bid = min(bid, 0.7 * budget)

    bid = max(0.0, min(float(budget), bid))
    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = int(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    if not alive_opps:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Extract yesterday bids to infer who pressures the market
    yesterday_bids = []
    yesterday = {}  # opp_id -> prev_trace
    for opp_id, opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        yesterday[opp_id] = prev
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0
    avg_prev_bid = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 0.0

    # Supply pressure: when supply is near the minimum, water is scarce -> bid higher
    scarcity = 0.0
    if MAX_SUPPLY > MIN_SUPPLY:
        scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    scarcity = max(0.0, min(1.0, scarcity))

    # Identify likely aggressive opponent (Cindy-like behavior): very high budget yesterday implies willingness to pay
    aggressive_score = 0.0
    for opp_id, opp in alive_opps:
        prev = yesterday.get(opp_id, {}) or {}
        prev_budget = opp.get('budget', 0.0)
        prev_bid = prev.get('bid', None)
        prev_bid_val = float(prev_bid) if prev_bid is not None else 0.0
        # If they bid high relative to salary or have huge budget, treat as aggressive
        if prev_bid is not None:
            aggressive_score = max(aggressive_score, prev_bid_val)
        # Also incorporate current budget as a tie-breaker
        if float(prev_budget) > 3.0 * DAILY_SALARY:
            aggressive_score = max(aggressive_score, prev_bid_val)

    # Base bid target: beat the top yesterday bid when scarcity is high, otherwise stay near average
    # Use small overbid to win without overpaying.
    target = 0.0
    if scarcity >= 0.65:
        # Tight supply: try to outbid yesterday's max by a margin
        target = highest_prev_bid + 5.0
    elif scarcity >= 0.35:
        # Medium supply: hover around avg and slightly above aggressive signal
        target = max(avg_prev_bid, aggressive_score) + 2.5
    else:
        # Plenty supply: conserve budget
        target = max(DAILY_SALARY * 0.45, avg_prev_bid * 0.7)

    # Survival urgency: if we're low hp or have gone without water, increase bid
    urgency = 0.0
    if hp <= 2:
        urgency = 1.0
    elif hp <= 3:
        urgency = 0.7
    elif hp <= 4:
        urgency = 0.4
    else:
        urgency = 0.2

    if no_water_days >= 2:
        urgency = max(urgency, 0.75)

    # Apply urgency multiplier
    target *= (0.85 + 0.35 * urgency)

    # Clamp to feasible range based on budget
    # Never bid more than budget; also avoid bidding near-total budget unless extremely urgent.
    max_reasonable = budget
    if urgency < 0.75:
        max_reasonable = min(budget, DAILY_SALARY * 1.25)
    else:
        max_reasonable = min(budget, DAILY_SALARY * 1.8)

    bid = max(0.0, min(target, max_reasonable))

    # If budget is low, still bid something to attempt survival
    if bid <= 0.0:
        bid = min(budget, DAILY_SALARY * 0.3)

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 140
    WATER_REQ = 8
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']
    supply = day_context['supply']

    alive_opponents = {k: v for k, v in opponents_status.items() if v['alive']}
    if not alive_opponents:
        bid = min(budget, DAILY_SALARY * 0.4)
        return max(0, bid)

    yesterday_bids = []
    for opp in alive_opponents.values():
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # Determine max yesterday bid
    max_prev_bid = max(yesterday_bids) if yesterday_bids else 0

    # Base bid strategy
    # If we are desperate (low HP or already missing water), bid high
    if hp <= 2 or no_water_days >= 1:
        base_bid = DAILY_SALARY * 0.9
    elif hp <= 4:
        base_bid = DAILY_SALARY * 0.75
    else:
        base_bid = DAILY_SALARY * 0.55

    # Adjust based on supply: lower supply -> more competition
    supply_factor = 1.0
    if supply < 18:
        supply_factor = 1.2
    elif supply > 22:
        supply_factor = 0.85

    # Adjust based on yesterday's max bid
    # If yesterday's max was very high, we may need to match or exceed
    if max_prev_bid > DAILY_SALARY * 0.85:
        # If we are healthy, we can lower a bit; if desperate, raise
        if hp <= 3:
            target_bid = max_prev_bid + 1.0
        else:
            target_bid = max_prev_bid * 0.9
    else:
        target_bid = max(base_bid, max_prev_bid + 0.5)

    # Apply supply factor
    final_bid = target_bid * supply_factor

    # Ensure we don't bid more than budget, but also not less than 0
    final_bid = min(budget, final_bid)
    final_bid = max(0, final_bid)

    return final_bid
